# Source for q/ae-chd-ie-prost.js: Congenital + Endocarditis + Prosthetic valves (second batch).
CG="Congenital"; IE="Endocarditis"; PV="Prosthetic valves"
Q=[
# --- Congenital ---
(CG,"A persistent left superior vena cava is suggested by a dilated coronary sinus. Confirmation is by:","Agitated saline injected into a left arm vein filling the coronary sinus before the RA",["Saline in the right arm filling the LA first","Color Doppler of the aorta","An exercise test"],"The left SVC drains into the coronary sinus in most cases.","F"),
(CG,"A cleft anterior mitral leaflet is most often associated with:","Primum ASD (partial AV canal defect)",["Secundum ASD","PDA","Coarctation"],"It causes mitral regurgitation through the cleft.","F"),
(CG,"A Gerbode defect is a shunt from the:","LV to the RA",["RA to the LA","Aorta to the PA","RV to the LV"],"Its high-velocity jet into the RA can be mistaken for TR and lead to a falsely high RVSP.","C"),
(CG,"A perimembranous VSD can get smaller or close as:","Tricuspid valve tissue (a 'septal aneurysm') covers it",["The aorta grows","Pulmonary pressure falls","The mitral valve calcifies"],"This is a common way small perimembranous VSDs close.","F"),
(CG,"In Ebstein anomaly, apical displacement of the septal tricuspid leaflet is significant when it is more than about:","8 mm/m² (indexed to BSA) from the mitral hinge point",["1 mm","2 mm/m²","30 mm/m²"],"Normal offset is small, with the tricuspid slightly more apical.","C"),
(CG,"Ebstein anomaly is commonly associated with:","An ASD or PFO and Wolff–Parkinson–White syndrome",["Coarctation","Bicuspid aortic valve","Kawasaki disease"],"Right-to-left shunting at the atrial level can cause cyanosis.","F"),
(CG,"After arterial switch surgery for d-TGA, echo follow-up looks for:","Supravalvular pulmonary or aortic narrowing, neo-aortic regurgitation and coronary problems",["Mitral stenosis","Ebstein anomaly","Pericardial constriction always"],"The coronary arteries are moved to the new aorta during surgery.","C"),
(CG,"After an atrial switch (Mustard or Senning) operation, the systemic ventricle is the:","Morphologic right ventricle",["Morphologic left ventricle","Single atrium","Pulmonary artery"],"Long-term systemic RV failure and baffle leaks or obstruction are concerns.","C"),
(CG,"In congenitally corrected transposition, a common late problem is:","Regurgitation of the systemic (tricuspid) AV valve and complete heart block",["Mitral stenosis","Aortic stenosis","Pulmonary vein stenosis"],"The tricuspid valve and morphologic RV support the systemic circulation.","C"),
(CG,"Tricuspid atresia requires which defect for survival?","An atrial-level communication (ASD or PFO)",["A mitral stenosis","A coarctation","An aortic stenosis"],"Blood must cross the atrial septum because it cannot enter the RV.","F"),
(CG,"A bidirectional Glenn operation connects the:","Superior vena cava to the pulmonary artery",["IVC to the aorta","LA to the RA","Aorta to the PA"],"It is often a step before the Fontan operation.","F"),
(CG,"A Blalock–Taussig shunt connects a systemic artery (usually the subclavian) to the:","Pulmonary artery",["Left atrium","Aorta","Coronary sinus"],"It shows continuous flow on Doppler.","F"),
(CG,"Fontan circulation flow in the pulmonary arteries is typically:","Low velocity and phasic with breathing, without a pumping ventricle",["High velocity over 3 m/s","Pulsatile like an artery","Absent"],"Look for thrombus, obstruction and fenestration flow.","C"),
(CG,"Pulmonary valve stenosis usually shows:","Doming leaflets in systole and post-stenotic dilation of the main PA",["Fused mitral leaflets","A dilated aortic root","LV hypertrophy only"],"Balloon valvuloplasty is the usual treatment.","F"),
(CG,"DiGeorge (22q11 deletion) syndrome is associated with:","Conotruncal defects such as truncus arteriosus, interrupted aortic arch and tetralogy of Fallot",["Mitral prolapse","Bicuspid aortic valve only","Ebstein anomaly"],"Patients may also have low calcium and immune problems.","C"),
(CG,"Holt–Oram syndrome combines:","ASD (or other septal defects) with upper limb abnormalities",["Coarctation with webbed neck","PDA with deafness","AV canal with Down syndrome"],"It is inherited as autosomal dominant.","C"),
(CG,"Congenital rubella syndrome is associated with:","PDA and branch pulmonary artery stenosis",["Tetralogy of Fallot","HCM","Coarctation"],"It also causes deafness and cataracts.","C"),
(CG,"Infants of mothers with poorly controlled diabetes may show:","Thickened septum (septal hypertrophy), which usually resolves",["Dilated cardiomyopathy","Aortic dissection","Ebstein anomaly"],"There is also a higher rate of congenital defects like TGA.","C"),
(CG,"Double outlet right ventricle means:","Both great arteries arise mostly from the RV",["Both arise from the LV","There is a single great artery","The RV has two chambers"],"A VSD is the only outflow from the LV.","F"),
(CG,"Interrupted aortic arch requires which connection for blood to reach the lower body?","A patent ductus arteriosus",["An ASD","A VSD only","A coronary fistula"],"It is a duct-dependent lesion needing prostaglandin.","C"),
(CG,"An aortopulmonary window is:","A defect between the ascending aorta and main pulmonary artery with two separate valves",["A VSD","A PDA","Truncus arteriosus"],"Truncus has one common valve; AP window has two.","C"),
(CG,"The most common congenital heart defects found for the first time in adults (other than bicuspid aortic valve) are:","Atrial septal defects",["Tetralogy of Fallot","TGA","Hypoplastic left heart"],"Many adults have no symptoms until their 30s or 40s.","F"),
(CG,"A PDA from the PSAX view shows color flow:","Entering the main PA near the left pulmonary artery origin, often throughout the cardiac cycle",["In the LVOT","Across the mitral valve","Into the RA"],"Continuous flow toward the transducer is typical.","F"),
(CG,"In a large ASD, the septum often moves:","Paradoxically, because of RV volume overload",["Normally","Only in diastole toward the RV","Not at all"],"The RV is dilated and the PA may be enlarged.","F"),
(CG,"Medicines used to close a PDA in premature babies include:","Indomethacin or ibuprofen",["Prostaglandin E1","Adenosine","Digoxin"],"Prostaglandin E1 keeps the ductus open.","F"),
(CG,"Pulmonary atresia with an intact ventricular septum often has:","A small RV and coronary connections from the RV (sinusoids)",["A large RV","A normal pulmonary valve","A large aorta only"],"Flow to the lungs depends on the ductus.","C"),
(CG,"After TOF repair, cardiac MRI is used to follow RV volume because:","Pulmonary valve replacement timing depends on RV size and function",["Echo cannot see the RV at all","MRI shows PR velocity better than Doppler","It is cheaper"],"Echo screens for PR severity, RVOT obstruction and RV pressure.","F"),
# --- Endocarditis ---
(IE,"The most common organism causing infective endocarditis today is:","Staphylococcus aureus",["E. coli","Candida","Pseudomonas"],"Viridans streptococci from the mouth are also common.","F"),
(IE,"Early prosthetic valve endocarditis (within about a year of surgery) is often caused by:","Coagulase-negative staphylococci (such as S. epidermidis)",["Viridans streptococci","HACEK organisms only","E. coli"],"These skin bacteria can contaminate the valve at surgery.","C"),
(IE,"Culture-negative endocarditis can be caused by:","Prior antibiotics, HACEK organisms, Coxiella or Bartonella",["Only S. aureus","Only viruses","Normal flora only"],"Special tests are needed to find the cause.","C"),
(IE,"Surgery is usually recommended in endocarditis for:","Heart failure from valve damage, uncontrolled infection (abscess) or high embolism risk",["Small vegetations with no complications","Mild regurgitation alone","Any fever"],"Early surgery improves outcomes in these patients.","F"),
(IE,"Right-sided (tricuspid) endocarditis often causes:","Septic emboli to the lungs",["Stroke","Kidney stones","Coronary emboli"],"Left-sided vegetations embolize to the brain, spleen and kidneys.","F"),
(IE,"A 'kissing' lesion on the anterior mitral leaflet can occur in aortic valve endocarditis when:","The AR jet strikes the mitral leaflet and spreads infection",["The mitral valve is prosthetic","The patient has MS","The LV is dilated"],"Look carefully at the anterior mitral leaflet in aortic valve IE.","C"),
(IE,"A new prolonged PR interval or heart block in aortic valve endocarditis suggests:","An aortic root abscess extending into the conduction system",["Normal healing","Mitral stenosis","Pericarditis only"],"This needs urgent TEE and surgical review.","C"),
(IE,"If the first TEE is negative but endocarditis is still strongly suspected, the usual approach is to:","Repeat TEE in about 5 to 7 days",["Never repeat","Do a chest X-ray instead","Repeat the TTE in a year"],"Vegetations may be too small to see early.","F"),
(IE,"Infection of a pacemaker or ICD lead (device endocarditis) is usually treated with:","Removal of the entire device system plus antibiotics",["Antibiotics alone in all cases","Leaving the device in place","Valve surgery only"],"Vegetations may be seen on leads or the tricuspid valve.","F"),
(IE,"TTE sensitivity for native valve vegetations is about:","60–70%, compared with over 90% for TEE",["100%","10%","Over 99% for prosthetic valves"],"TEE is much better for prosthetic valves and small lesions.","F"),
(IE,"Fungal endocarditis tends to cause:","Large vegetations with a high embolism risk",["Tiny vegetations only","No vegetations","Only pericarditis"],"Risk factors include IV lines, immune suppression and prosthetic valves.","C"),
(IE,"A mycotic aneurysm is:","An infected arterial aneurysm caused by septic emboli",["A fungal tumor","A coronary spasm","A normal finding"],"It can occur in brain arteries after endocarditis.","C"),
(IE,"Antibiotic prophylaxis before dental work is recommended for patients with:","Prosthetic valves or previous endocarditis",["Mild MVP without MR","Hypertension","Normal echo"],"Certain congenital conditions are also included.","F"),
(IE,"Abscesses in endocarditis are most common around the:","Aortic valve and prosthetic valves",["Pulmonic valve only","Tricuspid valve only","LAA"],"They can lead to fistulas and pseudoaneurysms.","F"),
(IE,"Thin, mobile fibrin strands on a prosthetic valve after surgery are:","Common and usually not infection, but should be noted and followed",["Always infection","Always thrombus","Tumors"],"Interpret together with clinical signs and cultures.","C"),
(IE,"Endocarditis can cause a fistula, which on color Doppler appears as:","Abnormal flow between two chambers or between the aorta and a chamber",["Absent flow","Normal laminar flow","Only aliasing in the LVOT"],"An aorta-to-RA or aorta-to-LA fistula needs surgery.","F"),
(IE,"Rheumatic fever is diagnosed with the Jones criteria, and echo helps by showing:","Carditis signs such as pathological MR or AR, even without a murmur",["Coronary aneurysms","LV noncompaction","Aortic dissection"],"Echo screening finds hidden rheumatic heart disease in at-risk regions.","F"),
# --- Prosthetic valves ---
(PV,"A normal bileaflet mechanical valve has how many orifices?","Three: two large side orifices and a small central one",["One central orifice","Two","Four"],"Velocities can be higher in the central orifice.","F"),
(PV,"For a mechanical aortic prosthesis, an acceleration time over about 100 ms suggests:","Prosthetic obstruction",["Normal function","Paravalvular leak","Low gradient always"],"Normal acceleration time is under about 80 ms.","C"),
(PV,"A DVI (LVOT VTI ÷ prosthetic VTI) under 0.25 for an aortic prosthesis suggests:","Significant prosthetic stenosis",["Normal function","Aortic regurgitation","High flow"],"Values of 0.30 or more are usually normal.","F"),
(PV,"For a mitral prosthesis, a mean gradient of 5 mmHg or less and peak E under 1.9 m/s are:","Usually normal",["Signs of severe stenosis","Signs of a leak","Not measurable"],"Higher values need a check for stenosis, MR or high flow.","F"),
(PV,"A mitral prosthesis VTI ratio (VTI prosthesis ÷ VTI LVOT) over about 2.5 suggests:","Prosthetic stenosis or significant regurgitation",["Normal function","Low flow","Aortic stenosis"],"A ratio under 2.2 is usually normal.","C"),
(PV,"Why is the 220 ÷ PHT formula not valid for mitral prostheses?","It was developed for native rheumatic MS and is not accurate for prostheses",["It is too accurate","Prostheses have no PHT","It overestimates heart rate"],"A PHT over about 200 ms still suggests obstruction.","C"),
(PV,"Severe aortic prosthesis–patient mismatch is defined by an indexed EOA of:","0.65 cm²/m² or less",["2.0 cm²/m²","1.5 cm²/m²","Any value"],"0.66–0.85 cm²/m² is moderate.","C"),
(PV,"Structural valve deterioration of a bioprosthesis shows:","Leaflet thickening, calcification or tears with rising gradient or new regurgitation",["Thinner leaflets","Lower gradients","No change over time"],"It often occurs after 10 to 15 years.","F"),
(PV,"Valve-in-valve TAVR is used to treat:","A failed surgical bioprosthesis",["A new mechanical valve","Mitral stenosis in rheumatic disease only","A PFO"],"A small original valve can lead to mismatch.","F"),
(PV,"Subclinical leaflet thrombosis after TAVR is often found as:","Thickened leaflets with reduced motion on CT",["Pericardial effusion","Mitral stenosis","Coarctation"],"A rising gradient on echo may be the first clue.","C"),
(PV,"Patients with mechanical valves need lifelong:","Warfarin anticoagulation",["DOACs","Aspirin alone","No blood thinners"],"DOACs are not approved for mechanical valves.","F"),
(PV,"A baseline echo after valve replacement is usually done:","Within weeks to a few months after surgery",["Only after 10 years","Never","Before surgery only"],"It gives a reference for future comparison.","F"),
(PV,"In the Ross procedure, the diseased aortic valve is replaced with the:","Patient's own pulmonic valve, and the pulmonic valve is replaced with a homograft",["A mechanical valve","A pig valve","Nothing"],"Follow-up watches both the autograft and homograft.","C"),
(PV,"Paravalvular regurgitation is graded as severe when it involves about:","30% or more of the sewing ring circumference",["1%","5%","Never graded"],"Under 10% is mild; 10% to 29% is moderate.","C"),
(PV,"SAM can occur after mitral repair because:","Excess posterior leaflet tissue pushes the coaptation point toward the LVOT",["The annulus is too large","The aortic valve is stenotic","The LV is dilated"],"Fluids and beta-blockers may help; sometimes more surgery is needed.","C"),
(PV,"Obstruction of a mechanical valve by fresh thrombus can be treated with:","Thrombolysis or surgery depending on the case",["Antibiotics only","No treatment","A pacemaker"],"Pannus does not respond to thrombolysis.","F"),
(PV,"Warfarin is a concern during pregnancy because it:","Can harm the baby (embryopathy), especially in the first trimester",["Causes valve calcification","Improves valve function","Has no effect"],"Valve choice in young women must consider future pregnancy.","F"),
(PV,"In a mitral bioprosthesis, the struts (stent posts) point:","Into the LV",["Into the LA","Into the aorta","Toward the pulmonary veins"],"Stent posts can sometimes obstruct the LVOT.","C"),
(PV,"A bioprosthetic valve in a young patient usually:","Degenerates faster than in older patients",["Lasts forever","Never needs replacement","Lasts longer than a mechanical valve"],"This is why mechanical valves are often chosen for younger patients.","F"),
(PV,"Fluoroscopy (cinefluoroscopy) is helpful for mechanical valves because it shows:","Disc or leaflet opening and closing angles",["Gradients","Regurgitant volume","LV mass"],"It can confirm a stuck leaflet.","C"),
]
